const event = $json.body?.events?.[0];
if (!event?.replyToken) return [];

const text = event.message?.type === 'text' ? event.message.text.trim() : '';
const keywords = ['設定資料', '健康資料', '建立檔案', '開始設定'];
const shouldReply = event.type === 'follow' || keywords.some(keyword => text.includes(keyword));
if (!shouldReply) return [];

return [{
  json: {
    replyToken: event.replyToken,
    messages: [{
      type: 'flex',
      altText: '建立健康檔案，開始設定你的基本資料',
      contents: {
        type: 'bubble',
        size: 'mega',
        body: {
          type: 'box',
          layout: 'vertical',
          paddingAll: '24px',
          backgroundColor: '#F4F8F5',
          contents: [
            { type: 'text', text: 'HEALTH PROFILE', size: 'xs', weight: 'bold', color: '#187A59' },
            { type: 'text', text: '建立你的健康檔案', size: 'xl', weight: 'bold', color: '#19342C', margin: 'md' },
            { type: 'text', text: '只需要基本資料，就能獲得更適合你的健康內容。', size: 'sm', color: '#6D8179', wrap: true, margin: 'sm' },
            { type: 'separator', color: '#DCE9E2', margin: 'xl' },
            {
              type: 'box', layout: 'vertical', spacing: 'sm', margin: 'xl', contents: [
                { type: 'text', text: '✓ 約 1 分鐘即可完成', size: 'sm', color: '#537168' },
                { type: 'text', text: '✓ 提供個人化健康建議', size: 'sm', color: '#537168' },
                { type: 'text', text: '✓ 健康資料妥善保護', size: 'sm', color: '#537168' }
              ]
            },
            {
              type: 'button', style: 'primary', height: 'sm', color: '#187A59', margin: 'xl',
              action: { type: 'uri', label: '開始設定健康資料', uri: 'https://liff.line.me/2010801069-26iRMu35' }
            }
          ]
        }
      }
    }]
  }
}];

let data = $json.body;
if (typeof data === 'string') {
  try { data = JSON.parse(data); } catch { throw new Error('無法解析健康資料'); }
}

if (data.recordType === 'sleepQuality') {
  const durationMinutes = Number(data.durationMinutes);
  const energyLevel = Number(data.energyLevel);
  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(data.bedTime || '')) throw new Error('入睡時間格式錯誤');
  if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(data.wakeTime || '')) throw new Error('起床時間格式錯誤');
  if (!Number.isFinite(durationMinutes) || durationMinutes < 1 || durationMinutes > 1440) throw new Error('睡眠時數超出範圍');
  if (!Number.isInteger(energyLevel) || energyLevel < 1 || energyLevel > 5) throw new Error('精神程度超出範圍');
  const sleep = { recordType: 'sleepQuality', bedTime: data.bedTime, wakeTime: data.wakeTime, durationMinutes, durationHours: Number((durationMinutes / 60).toFixed(2)), energyLevel, dreamNote: String(data.dreamNote || '').slice(0, 200), lineUserId: data.lineUserId || null, recordedAt: data.recordedAt || new Date().toISOString() };
  return [{ json: { ok: true, recordType: 'sleepQuality', sleep } }];
}

const age = Number(data.age);
const heightCm = Number(data.heightCm);
const weightKg = Number(data.weightKg);
const allowedGenders = ['female', 'male', 'other'];
if (!allowedGenders.includes(data.gender)) throw new Error('生理性別格式錯誤');
if (!Number.isFinite(age) || age < 1 || age > 120) throw new Error('年齡超出範圍');
if (!Number.isFinite(heightCm) || heightCm < 80 || heightCm > 250) throw new Error('身高超出範圍');
if (!Number.isFinite(weightKg) || weightKg < 20 || weightKg > 400) throw new Error('體重超出範圍');
const bmi = Number((weightKg / ((heightCm / 100) ** 2)).toFixed(1));
return [{ json: { ok: true, recordType: 'healthProfile', profile: { gender: data.gender, age, heightCm, weightKg, bmi, lineUserId: data.lineUserId || null, displayName: data.displayName || null, updatedAt: new Date().toISOString() } } }];
